package org.kanger;
import java.util.*;
import org.kanger.ContextProductionCapture.Source;
import org.kanger.ContextProductionCapture.Support;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextProductionNativeBinding.Entry;
import org.kanger.ContextWitnessResultTransport.*;

/** Private roots are local evidence; only proved X-dependent products may cross a barrier. */
public final class ContextPrivateWitnessPoolRunner {
    static int checks;static final int WORK=64000000,EVENTS=500000;
    static final String MID="!@w seed(w,1)->mid(w,1);",DONE="!@w mid(w,1)->done(w,1);",NEG="!@w done(w,1)->~flag(w,1);",BUNDLE="!$w seed(w,1)&&flag(w,1);";
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    interface Action{void run()throws Exception;}
    static void reject(Action a,String why)throws Exception{boolean seen=false;try{a.run();}catch(IllegalArgumentException|IllegalStateException e){seen=true;}require(seen,why);}
    static Snapshot bind(boolean local,String text)throws Exception{return ContextTrustedWitnessScopeRunner.bind(local,text);}
    static Source source(Snapshot s,String text){return s.primary.stream().filter(e->e.statement.equals(text)).findFirst().get().source;}
    static Packet common(Snapshot x){ContextWitnessResultTransport.Result r=ContextWitnessResultTransport.primarySeeds(x,WORK);require(r.exported,"sealed X common seeds");return r.packet;}
    static Item item(Packet p,String pred){return p.items.stream().filter(i->i.atom.predicate.equals(pred)).findFirst().get();}
    static void proof(Item item,Set<Source> sources,int depth){require(item.proofs.stream().anyMatch(p->p.sources.equals(sources)&&p.depth==depth),"exact original whole-source support and depth");}
    static void one(boolean reverse,boolean split)throws Exception{
        Snapshot x=bind(true,"!anchor(1); "+MID+" "+NEG),a=bind(false,split?"!$w seed(w,1); !$w flag(w,1);":BUNDLE),b=bind(false,DONE);Snapshot group=ContextProductionNativeBinding.trusted("own",reverse?Arrays.asList(b,a):Arrays.asList(a,b),WORK);Packet initial=common(x);PrivatePool p=ContextWitnessResultTransport.privatePool(initial,x,group,WORK);
        require(p.common==initial&&p.snapshot==group,"exact owning common/cut binding");require(initial.items.size()==1&&initial.items.stream().noneMatch(i->i.atom.predicate.equals("seed")||i.atom.predicate.equals("flag")),"raw private facts absent from common X");Item raw=item(p.local,"seed"),flag=item(p.local,"flag");Source seedSource=a.primary.stream().filter(e->e.statement.contains("seed(")).findFirst().get().source;
        require(raw.atom.arguments.get(0).origin.source.equals(seedSource)&&!seedSource.localX&&raw.atom.arguments.get(0).origin.binder==0,"private original member Source/binder preserved");require(split?!raw.atom.arguments.get(0).origin.equals(flag.atom.arguments.get(0).origin):raw.atom.arguments.get(0).origin.equals(flag.atom.arguments.get(0).origin),"whole-bundle sharing and independent bundles stay distinct");proof(raw,Collections.singleton(seedSource),0);reject(()->ContextWitnessResultTransport.family(p.local,Collections.singletonList(p.cut),WORK),"raw local pool cannot become an authenticated common family packet");
        Packet first;UUID namespace;
        try(ContextWitnessSeedReplay pass=ContextWitnessSeedReplay.openPrivate(p,WORK,EVENTS)){
            namespace=pass.namespace;pass.rule(source(x,MID),MID);ContextWitnessResultTransport.Result out=ContextWitnessResultTransport.exportNext(pass,16,WORK);require(out.exported,"X-dependent private-root product: "+out.reason);first=out.packet;require(first.basis.equals(initial.identity)&&first.coveredCut==null&&first.roundCut==null,"observed result is no family closure permission");List<org.kanger.ContextProductionInputs.Declaration> definitions=Collections.singletonList(new org.kanger.ContextProductionInputs.Declaration(source(x,MID),MID));ContextWitnessResultTransport.Result forbidden=ContextWitnessResultTransport.exportRoundNext(pass,p.cut,definitions,16,WORK,EVENTS);require(!forbidden.exported&&forbidden.packet==null&&forbidden.reason.contains("no family coverage"),"unfinished private coverage cannot obtain a round certificate");
        }
        require(first.items.stream().noneMatch(i->i.atom.predicate.equals("seed")||i.atom.predicate.equals("flag")),"private raw atoms never promoted to common output");Item mid=item(first,"mid");require(mid.atom.arguments.get(0).origin.equals(raw.atom.arguments.get(0).origin),"foreign origin does not become an invented X witness");proof(mid,new HashSet<>(Arrays.asList(seedSource,source(x,MID))),1);
        PrivatePool next=ContextWitnessResultTransport.privatePool(first,x,group,WORK);require(item(next.local,"mid").atom.arguments.get(0).origin.equals(item(next.local,"seed").atom.arguments.get(0).origin),"same private witness reintroduced at next common input");Packet second;
        try(ContextWitnessSeedReplay pass=ContextWitnessSeedReplay.openPrivate(next,WORK,EVENTS)){require(!pass.namespace.equals(namespace),"fresh native replay namespace");require(pass.bindings.size()==(split?2:1),"canonical roots reused, never duplicated on private reinjection");pass.rule(source(b,DONE),DONE);ContextWitnessResultTransport.Result out=ContextWitnessResultTransport.exportNext(pass,16,WORK);require(out.exported,"next X-dependent member step: "+out.reason);second=out.packet;}
        Item done=item(second,"done");require(done.atom.arguments.get(0).origin.equals(raw.atom.arguments.get(0).origin),"original private origin survives two fresh replays");proof(done,new HashSet<>(Arrays.asList(seedSource,source(x,MID),source(b,DONE))),2);require(second.items.stream().noneMatch(i->i.atom.predicate.equals("seed")||i.atom.predicate.equals("flag")),"private flag still local after later member step");
        PrivatePool last=ContextWitnessResultTransport.privatePool(second,x,group,WORK);ContextWitnessClauseCollision.Result shared=ContextWitnessClauseCollision.inspect(second,last.cut,last.declarations,16,WORK,EVENTS),local=ContextWitnessClauseCollision.inspectPrivate(last,16,WORK,EVENTS);require(shared.scanned&&shared.evidence.isEmpty(),"common-only scan lacks private flag and cannot prove this refutation");require(local.scanned&&local.status==(split?ContextWitnessClauseCollision.Status.INCOMPLETE:ContextWitnessClauseCollision.Status.COLLISION),"local original witness identity determines direct refutation: "+local.reason);if(split)require(local.evidence.isEmpty(),"independent flag witness never aliases private seed");else for(ContextWitnessClauseCollision.Evidence e:local.evidence){require(e.producer.equals(source(x,NEG)),"exact whole negative X refuter");for(Support support:e.proofs)require(support.depth==3&&support.sources.equals(new HashSet<>(Arrays.asList(seedSource,source(x,MID),source(b,DONE),source(x,NEG)))),"original four-source local opposition at cumulative depth3");}
        require(!ContextProductionFamilyAssembly.assemble(x,Arrays.asList(group),WORK).assembled,"private local primitives do not enable incomplete family admission");
    }
    static void boundaries()throws Exception{
        Snapshot x=bind(true,"!anchor(1);"),a=bind(false,BUNDLE),raw=bind(false,"!@w seed(w,1)->raw(w,1);");Packet initial=common(x);Snapshot group=ContextProductionNativeBinding.trusted("own",Arrays.asList(a,raw),WORK);PrivatePool local=ContextWitnessResultTransport.privatePool(initial,x,group,WORK);
        try(ContextWitnessSeedReplay pass=ContextWitnessSeedReplay.openPrivate(local,WORK,EVENTS)){pass.rule(raw.primary.get(0).source,raw.primary.get(0).statement);ContextWitnessResultTransport.Result out=ContextWitnessResultTransport.exportNext(pass,16,WORK);require(!out.exported&&out.packet==null&&out.reason.contains("No X-dependent"),"pure private inference cannot borrow unrelated X anchor for export");}
        Snapshot bothX=bind(true,"!$w seed(w,1); "+MID);Packet bothCommon=common(bothX);PrivatePool mixed=ContextWitnessResultTransport.privatePool(bothCommon,bothX,group,WORK);Source xOrigin=bothX.primary.stream().filter(e->e.bundle!=null).findFirst().get().source,privateOrigin=a.primary.get(0).source;
        try(ContextWitnessSeedReplay pass=ContextWitnessSeedReplay.openPrivate(mixed,WORK,EVENTS)){require(pass.bindings.size()==2,"X and private binder0 are distinct even under one native carrier");pass.rule(source(bothX,MID),MID);ContextWitnessResultTransport.Result out=ContextWitnessResultTransport.exportNext(pass,16,WORK);require(out.exported,"mixed-origin X-dependent products");Set<Source> origins=new HashSet<>();for(Item v:out.packet.items)if(v.atom.predicate.equals("mid"))origins.add(v.atom.arguments.get(0).origin.source);require(origins.equals(new HashSet<>(Arrays.asList(xOrigin,privateOrigin))),"both root namespaces preserved without alias or invented X ownership");require(out.packet.items.stream().filter(v->v.atom.predicate.equals("seed")).allMatch(v->v.atom.arguments.get(0).origin.source.equals(xOrigin)),"only already-common seed stays common, private seed does not leak");}
        Snapshot bad=bind(false,"!@w seed(w,1)->~flag(w,1);"),inconsistent=ContextProductionNativeBinding.trusted("local",Arrays.asList(a,bad),WORK);ContextWitnessClauseCollision.Result scan=ContextWitnessClauseCollision.inspectPrivate(ContextWitnessResultTransport.privatePool(initial,x,inconsistent,WORK),16,WORK,EVENTS);require(scan.scanned&&scan.evidence.isEmpty()&&scan.status==ContextWitnessClauseCollision.Status.INCOMPLETE,"private-only contradiction cannot invent X dependence or imply consistency");
        reject(()->ContextWitnessResultTransport.privatePool(local.local,x,group,WORK),"local private pool cannot be re-labelled as common basis");reject(()->ContextWitnessResultTransport.privatePool(initial,x,x,WORK),"X is not a private target");reject(()->ContextWitnessResultTransport.privatePool(initial,bind(true,"!other(1);"),group,WORK),"another X inventory cannot own this pool");reject(()->ContextWitnessResultTransport.privatePool(initial,x,raw,WORK),"private bundle required, no guessed seeds");reject(()->ContextWitnessResultTransport.privatePool(initial,x,group,1),"bounded private preparation work");
        Snapshot signed=bind(false,"!$w seed(w,1)&&~flag(w,1);");reject(()->ContextWitnessResultTransport.privatePool(initial,x,signed,WORK),"negative private bundles remain explicit unsupported scope");Snapshot pair=bind(false,"!$u $v pair(u,v);");reject(()->ContextWitnessResultTransport.privatePool(initial,x,pair,WORK),"multi-witness literal not silently squeezed into single-origin transport");
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("private-witness-pool-").toString());for(boolean r:new boolean[]{false,true})for(boolean s:new boolean[]{false,true})one(r,s);boundaries();System.out.println("CONTEXT_PRIVATE_WITNESS_POOL_PASS checks="+(checks+ContextTrustedWitnessScopeRunner.checks));System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
